-- 605: Original BrillaPrep Cambridge IGCSE Chemistry (0620) sprint 3 beta questions, part 12 of 13 (batch igcse-chemistry-sprint3-001).
-- Curriculum-aligned practice content; not official Cambridge International, WAEC or NSMQ examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_605_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_605_guard;
INSERT INTO _migration_605_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_045' AND NOT (q.topic_id IS 'topic_igcse_chem_analysis' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'X is a white solid compound containing one cation and one anion. Answer the following questions about identifying X.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) potassium ions, K⁺; (b) add dilute acid — the gas evolved turns limewater milky; (c) potassium carbonate, K₂CO₃.' AND q.explanation IS '(a) A lilac flame is characteristic of potassium compounds. (b) Carbonates react with dilute acids to release carbon dioxide: CO₃²⁻ + 2H⁺ → H₂O + CO₂; bubbling the gas through limewater turns it milky as insoluble calcium carbonate forms. (c) Combining a potassium cation with a carbonate anion gives potassium carbonate, K₂CO₃.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '4' AND q.time_limit IS '300' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_045' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_605_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_046' AND NOT (q.topic_id IS 'topic_igcse_chem_reactions' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which change increases the rate of the reaction between marble chips and dilute hydrochloric acid?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Using larger marble chips.","B. Cooling the acid before use.","C. Diluting the acid with more water.","D. Using powdered marble chips instead of large lumps."]' AND q.correct_answer IS 'D' AND q.explanation IS 'Powdering the marble increases its surface area, so more particles are exposed to the acid and collisions are more frequent. (Larger chips reduce the surface area; cooling and diluting both slow the reaction.) Therefore the correct answer is D: Using powdered marble chips instead of large lumps..' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_046' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_605_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_047' AND NOT (q.topic_id IS 'topic_igcse_chem_reactions' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How does a catalyst increase the rate of a chemical reaction?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It provides an alternative reaction pathway with a lower activation energy.","B. It increases the temperature of the reactants.","C. It is used up during the reaction.","D. It increases the concentration of the reactants."]' AND q.correct_answer IS 'A' AND q.explanation IS 'A catalyst works by offering a route of lower activation energy, so a greater proportion of collisions are successful. It is chemically unchanged at the end and does not alter temperature or concentration. (A catalyst that was used up could not, by definition, be a catalyst.) Therefore the correct answer is A: It provides an alternative reaction pathway with a lower activation energy..' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_047' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_605_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_048' AND NOT (q.topic_id IS 'topic_igcse_chem_reactions' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'For the reaction H₂ + Cl₂ → 2HCl the bond energies are H–H = 436 kJ/mol, Cl–Cl = 243 kJ/mol and H–Cl = 432 kJ/mol. What is the enthalpy change, ΔH, of the reaction?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. +185 kJ/mol","B. −185 kJ/mol","C. −247 kJ/mol","D. +1,111 kJ/mol"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Energy taken in to break bonds = 436 + 243 = 679 kJ. Energy released forming two H–Cl bonds = 2 × 432 = 864 kJ. ΔH = 679 − 864 = −185 kJ/mol, so the reaction is exothermic. (+185 reverses the sign; −247 forms only one H–Cl bond; +1,111 adds the two energies instead of subtracting.) Therefore the correct answer is B: −185 kJ/mol.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_048' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_045', 'topic_igcse_chem_analysis', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'X is a white solid compound containing one cation and one anion. Answer the following questions about identifying X.', 'structured', NULL, NULL, '(a) potassium ions, K⁺; (b) add dilute acid — the gas evolved turns limewater milky; (c) potassium carbonate, K₂CO₃.', '(a) A lilac flame is characteristic of potassium compounds. (b) Carbonates react with dilute acids to release carbon dioxide: CO₃²⁻ + 2H⁺ → H₂O + CO₂; bubbling the gas through limewater turns it milky as insoluble calcium carbonate forms. (c) Combining a potassium cation with a carbonate anion gives potassium carbonate, K₂CO₃.', 'medium', '4', '4', '300', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_046', 'topic_igcse_chem_reactions', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Which change increases the rate of the reaction between marble chips and dilute hydrochloric acid?', 'multiple_choice', NULL, '["A. Using larger marble chips.","B. Cooling the acid before use.","C. Diluting the acid with more water.","D. Using powdered marble chips instead of large lumps."]', 'D', 'Powdering the marble increases its surface area, so more particles are exposed to the acid and collisions are more frequent. (Larger chips reduce the surface area; cooling and diluting both slow the reaction.) Therefore the correct answer is D: Using powdered marble chips instead of large lumps..', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_047', 'topic_igcse_chem_reactions', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'How does a catalyst increase the rate of a chemical reaction?', 'multiple_choice', NULL, '["A. It provides an alternative reaction pathway with a lower activation energy.","B. It increases the temperature of the reactants.","C. It is used up during the reaction.","D. It increases the concentration of the reactants."]', 'A', 'A catalyst works by offering a route of lower activation energy, so a greater proportion of collisions are successful. It is chemically unchanged at the end and does not alter temperature or concentration. (A catalyst that was used up could not, by definition, be a catalyst.) Therefore the correct answer is A: It provides an alternative reaction pathway with a lower activation energy..', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_048', 'topic_igcse_chem_reactions', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'For the reaction H₂ + Cl₂ → 2HCl the bond energies are H–H = 436 kJ/mol, Cl–Cl = 243 kJ/mol and H–Cl = 432 kJ/mol. What is the enthalpy change, ΔH, of the reaction?', 'multiple_choice', NULL, '["A. +185 kJ/mol","B. −185 kJ/mol","C. −247 kJ/mol","D. +1,111 kJ/mol"]', 'B', 'Energy taken in to break bonds = 436 + 243 = 679 kJ. Energy released forming two H–Cl bonds = 2 × 432 = 864 kJ. ΔH = 679 − 864 = −185 kJ/mol, so the reaction is exothermic. (+185 reverses the sign; −247 forms only one H–Cl bond; +1,111 adds the two energies instead of subtracting.) Therefore the correct answer is B: −185 kJ/mol.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'igcse-chemistry-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/', 0, 1 FROM questions WHERE id IN ('q_igcse_chem_s3_045', 'q_igcse_chem_s3_046', 'q_igcse_chem_s3_047', 'q_igcse_chem_s3_048');
